#!/bin/bash
# Быстрые проверки (~3 минуты): без звука и моделей распознавания; PostgreSQL — временный, если есть initdb — то, что гоняет GitHub на каждую запись.
# Полный набор — tests/run_all.sh. Использование: tests/run_quick.sh [python]
# Те же правила, что в run_all.sh: проверка пройдена, только если нет ❌ И код выхода 0.
TMPROOT=$(mktemp -d); export TMPDIR="$TMPROOT"; trap 'type _pg_stop >/dev/null 2>&1 && _pg_stop; rm -rf "$TMPROOT"' EXIT
PY=${1:-python3}; T="$(cd "$(dirname "$0")" && pwd)"; ROOT="$(dirname "$T")"
export PYTHONUNBUFFERED=1 DEWIAR_PY=${DEWIAR_PY:-$PY} DEWIAR_FAKE_RAM_GB=${DEWIAR_FAKE_RAM_GB:-16} DEWIAR_FAKE_CORES=${DEWIAR_FAKE_CORES:-8}
FAIL=0
gh_error() {   # в GitHub Actions — ещё и пометка с причиной: журнал целиком там видно не всем, пометки — всем
  [ -n "$GITHUB_ACTIONS" ] || return 0
  # в заголовке пометки «:» и «,» — разделители команды GitHub: без замены пометка молча пропадает (21.10: «Встречи»: …, …)
  local m=${2:-без подробностей — см. журнал шага} t=$1; m=${m//'%'/'%25'}; m=${m//$'\n'/'%0A'}; t=${t//'%'/'%25'}; t=${t//':'/'%3A'}; t=${t//','/'%2C'}; echo "::error title=$t::$m"
  local s="$1 — $(head -c 300 <<<"$2" | tr '\n' ' ')"; s=${s//'%'/'%25'}; echo "::error::$s"   # и простая пометка без заголовка — на случай, если заголовок не принят
  printf '### ❌ %s\n```\n%s\n```\n' "$1" "$2" >> "${GITHUB_STEP_SUMMARY:-/dev/null}"; }
# у каждой проверки — своя папка: и рабочая (DEWIAR_WORKSPACE_DIR), и временная (TMPDIR — tempfile.mkdtemp и mktemp
# внутри проверки); после — удаляется: раньше временные папки копились по сотне за прогон, и диск кончался (27.10)
# Оценка вывода одной проверки: пройдена, только если нет ❌, код 0 и есть хоть одна ✅ (или «ALL OK»).
passes() { [ "$1" = 0 ] && ! grep -q "❌" <<<"$2" && { grep -q "✅" <<<"$2" || grep -qE "ALL OK|^OK$" <<<"$2"; }; }
judge() { local name=$1 rc=$2 out=$3 note=$4
  local ok=$(grep -c "✅" <<<"$out"); local bad=$(grep "❌" <<<"$out")
  if passes "$rc" "$out"; then printf "✅ %-34s %s%s\n" "$name" "$ok" "$note"; return 0; fi
  printf "❌ %-34s (код %s)%s\n%s\n" "$name" "$rc" "$note" "$bad$(tail -5 <<<"$out")"; FAIL=1; gh_error "$name" "$bad
$(tail -15 <<<"$out")"; return 1; }
one() {   # выполнить проверку в своей папке -> вывод и в конце «RC=код»
  local ws; ws=$(mktemp -d); mkdir -p "$ws/tmp"
  # вывод — в файл, не в трубу: проверка, убитая по времени, оставляла живым ядро с её stdout — труба не закрывалась,
  # и весь прогон висел (03.11, kids1027). После — добиваем всё, что запущено с её TMPDIR
  DEWIAR_WORKSPACE_DIR=$ws TMPDIR=$ws/tmp timeout "${T_OUT:-300}" "$@" > "$ws/out.txt" 2>&1; local rc=$?
  tr -d "\r" < "$ws/out.txt"; echo "RC=$rc"; reap "$ws"; rm -rf "$ws"; }
reap() { local p; for p in /proc/[0-9]*; do grep -qzxF "TMPDIR=$1/tmp" "$p/environ" 2>/dev/null && kill -9 "${p#/proc/}" 2>/dev/null; done; return 0; }
# Несколько проверок сразу (28.10, владелец: «жаль, что так долго»): DEWIAR_JOBS=3 tests/run_quick.sh — проверки идут
# по три, итоги печатаются по порядку в конце. Упавшая в толпе перепроверяется одна — прошла одна, значит, мешала
# нагрузка (тайминги игр, анимации), в строке так и сказано: «со второго раза, одна». По умолчанию — по одной, как раньше.
JOBS=${DEWIAR_JOBS:-1}; Q="$TMPROOT/q"; mkdir -p "$Q"; N=0
sec() { if [ "$JOBS" -le 1 ]; then echo "$1"; else N=$((N+1)); printf '%s' "$1" > "$Q/$(printf %04d $N).sec"; fi; }
run() { local name=$1; shift
  if [ "$JOBS" -le 1 ]; then local out; out=$(one "$@"); local rc=${out##*RC=}; judge "$name" "$rc" "${out%RC=*}"; return; fi
  N=$((N+1)); local id; id=$(printf %04d $N); printf '%s' "$name" > "$Q/$id.name"
  # перепроверка в конце — с теми же T_OUT / JOIN_DB / RUNNER_DB, что у первого раза (их ставят перед run)
  { printf 'T_OUT=%q JOIN_DB=%q RUNNER_DB=%q one ' "${T_OUT:-300}" "${JOIN_DB:-}" "${RUNNER_DB:-}"; printf '%q ' "$@"; } > "$Q/$id.cmd"
  while [ "$(jobs -rp | wc -l)" -ge "$JOBS" ]; do wait -n 2>/dev/null || true; done
  ( one "$@" > "$Q/$id.out" ) & }
finish() { [ "$JOBS" -le 1 ] && return; wait
  for f in $(ls "$Q" | grep -E '\.(sec|name)$' | sort); do local id=${f%%.*}
    if [ "${f##*.}" = sec ]; then cat "$Q/$f"; echo; continue; fi
    local name; name=$(cat "$Q/$f"); local out; out=$(cat "$Q/$id.out"); local rc=${out##*RC=}; out=${out%RC=*}
    if passes "$rc" "$out"; then judge "$name" "$rc" "$out"; continue; fi
    out=$(eval "$(cat "$Q/$id.cmd")"); rc=${out##*RC=}; judge "$name" "$rc" "${out%RC=*}" " · со второго раза, одна"
  done; }

echo "== Синтаксис"
if cout=$($PY -m compileall -q -x '/(vendor|node_modules)/' "$ROOT/core" "$ROOT/ui" "$ROOT/tools" "$ROOT/server" "$ROOT/tests" "$ROOT/packaging/dewiar-server" 2>&1); then
  echo "✅ Python"; else echo "❌ Python"; echo "$cout" | tail -8; FAIL=1; gh_error Python "$(tail -8 <<<"$cout")"; fi
if command -v node >/dev/null; then
  bad=$(for f in "$ROOT"/android/assets/www/*.js "$ROOT"/ui/studio/*.js; do node --check "$f" 2>/dev/null || echo "$f"; done)
  [ -z "$bad" ] && echo "✅ JavaScript" || { echo "❌ JavaScript: $bad"; FAIL=1; gh_error JavaScript "$bad"; }
fi

